async def on_after_tool(self, event: ToolResultEvent):
    # Arm when the agent runs a command that looks like an HTTP service.
    if not self._service_seen:
        cmd = ""
        inp = getattr(event, "tool_input", None)
        if isinstance(inp, dict):
            cmd = str(inp.get("command", "") or "")
        if event.tool_name == "Bash" and _HTTP_SERVICE_RE.search(cmd):
            self._service_seen = True
    yield event

